import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Img } from '../remotionShim';


export type Chrome3DLogoProps = Record<string, any>;

const Chrome3DLogo: React.FC<Chrome3DLogoProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  logoUrl = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/6fef42da7eb444bca24c72777d8ab727.PNG",
  depth = 40,
  rotations = 1,
  logoSize = 700,
  chromeBrightness = 1.5,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  
  // Calculate total frames safely
  const totalFrames = Math.max(1, durationInSeconds * fps);

  // Safe background color handling
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // 360 Rotation mapping over the exact duration
  const rotationY = interpolate(frame, [0, totalFrames], [0, 360 * rotations]);

  // Subtle vertical floating animation to enhance the 3D feel
  const floatY = interpolate(
    Math.sin((frame / fps) * Math.PI * 0.5),
    [-1, 1],
    [-20, 20]
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          perspective: "2000px",
          transition: "none",
        }}
      >
        <div
          style={{
            width: logoSize,
            height: logoSize,
            position: "relative",
            transformStyle: "preserve-3d",
            transform: `translateY(${floatY}px) rotateY(${rotationY}deg)`,
            transition: "none",
          }}
        >
          {/* We generate the 3D extrusion by stacking multiple image layers on the Z-axis */}
          {Array.from({ length: depth }).map((_, i) => {
            const isFront = i === depth - 1;
            const isBack = i === 0;

            // Create a dynamic metallic shine traveling across the extruded edges
            // This simulates light reflecting off a rounded chrome surface as it spins
            const shineCenter = Math.floor(
              interpolate(Math.sin((frame / fps) * Math.PI * rotations), [-1, 1], [0, depth])
            );
            const distanceToShine = Math.abs(i - shineCenter);
            const shineIntensity = Math.max(0, 1 - distanceToShine / 8) * 1.5;

            // Base darkness of the extruded "metal" side, darker towards the back
            const baseBrightness = 0.2 + (i / depth) * 0.3;
            let brightness = baseBrightness + shineIntensity;

            // The absolute front and back faces are brightened to simulate the flat polished face
            if (isFront || isBack) brightness = chromeBrightness;

            // Add a glowing halo to the front layer to simulate high-shine polish
            const dropShadow = isFront
              ? "drop-shadow(0px 0px 40px rgba(255, 255, 255, 0.7))"
              : "";

            const filter = `brightness(${brightness}) ${dropShadow}`;

            return (
              <Img
                key={i}
                src={logoUrl}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  objectFit: "contain",
                  // Center the extrusion depth around the origin
                  transform: `translateZ(${i - depth / 2}px)`,
                  filter,
                  WebkitFilter: filter,
                  transition: "none",
                }}
              />
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

